        array("id" => "s3e2", "season" => 3, "number" => 2, "name" => "The Threat of \"Left\"", "airdate" => "14 Oct 2016", "runtime" => 25, "rating" => null, "summary" => "The Miyagi Prefecture Qualifier finals of the Spring High School Volleyball Tournament. From the very beginning of the match, Ushijima attacks with his powerful spikes. Because he's not used to left-handed attacks, their Guardian Deity, Nishinoya, has a hard…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/80/200134.jpg"),
        array("id" => "s3e3", "season" => 3, "number" => 3, "name" => "Guess-Monster", "airdate" => "21 Oct 2016", "runtime" => 25, "rating" => null, "summary" => "The match is now in the second match. Karasuno tries to attack, but Shiratorizawa's middle blocker, Tendo keeps blocking all of their attempts. As he blocked Karasuno's spikes on after another, Tsukishima calmly stared at their opponent's side of the court..S…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/81/203538.jpg"),
